-- Ulduar: SmartAI from TrinityCore 3.3.5 for creatures that only meleed here: the Thorim Trap Bunnies' Paralytic
-- Field, the Steelforged Defender, the Leviathan wing's trash (Arachnopod Destroyer and its Clockwork Mechanic,
-- Hardened Iron Golem, Clockwork Sapper, Rune Etched Sentry, Chamber Overseer, Iron Mender, Lightning Charged Iron
-- Dwarf) and the Winter Jormungars with the Snow Mounds that release them.
-- TrinityCore's difficulty flags 0x2 (10 player) and 0x4 (25 player) are 0x8 and 0x10 here.
-- Not ported: the Steelforged Defender's cast of 65387 on death (the spell is not in the 5.4.8 data). The Clockwork
-- Mechanic stuns itself with 62794 in place of 25900, and sets its not-selectable flag with SET_UNIT_FLAG.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (33054, 33236, 33725, 34137, 34146, 34150, 34151, 34183, 34184, 34190, 34193, 34196, 34197, 34198, 34199);
DELETE FROM `smart_scripts` WHERE (`source_type` = 0 AND `entryorguid` IN (33054, 33236, 33725, 34137, 34146, 34150, 34151, 34183, 34184, 34190, 34193, 34196, 34197, 34198, 34199)) OR (`source_type` = 9 AND `entryorguid` IN (3413700, 3414600, 3415000, 3415100));
